/* ═══════════════════════════════════════════════════════════════════════
   app_i18n.js — content-keyed runtime translator for app.html (TR/EN/ES).
   Pairs with the inline scaffold's t()/aiLang()/setLang()/APP_LANG.
   Translates STATIC UI text nodes + placeholders by exact source match.
   NEVER touches dynamic AI/user content: skips [data-i18n], [data-i18n-skip],
   [data-i18n-ph] and a fixed set of dynamic-content container ids.
   ═══════════════════════════════════════════════════════════════════════ */
(function(){
  // Dynamic-content containers whose whole subtree is verbatim AI/user text.
  var SKIP_IDS = {
    'rp-messages':1, 'convListEl':1, 'contactsListEl':1, 'recentMsgsWidget':1,
    'wowMirrorList':1, 'wowUnexpectedList':1, 'wowThemSummary':1,
    'wowArchetypeName':1, 'wowArchetypeTagline':1, 'wowArchetypeTraits':1,
    'wowLoopSteps':1, 'wowDnaBars':1, 'bysResult':1,
    'wowStatsCards':1, 'processingStats':1  // stat cards/chips render language-aware already
  };
  var origMap = new WeakMap();  // textNode -> original trimmed source string
  var origPh  = new WeakMap();  // element  -> original placeholder string
  function lang(){ return window.APP_LANG || 'tr'; }
  function inSkip(el){
    while (el && el.nodeType === 1){
      if (el.hasAttribute && (el.hasAttribute('data-i18n') || el.hasAttribute('data-i18n-skip') || el.hasAttribute('data-i18n-ph'))) return true;
      if (el.id && SKIP_IDS[el.id]) return true;
      var tn = el.tagName;
      if (tn === 'SCRIPT' || tn === 'STYLE' || tn === 'NOSCRIPT' || tn === 'TEXTAREA') return true;
      if (el.isContentEditable) return true;
      el = el.parentNode;
    }
    return false;
  }
  function translateTextNode(node){
    var dict = window.I18N_C; if (!dict) return;
    var parent = node.parentNode;
    if (!parent || parent.nodeType !== 1) return;
    if (inSkip(parent)) return;
    var cur = node.nodeValue;
    var trimmed = cur.trim();
    if (!trimmed || trimmed.length < 1) return;
    var key = origMap.get(node);
    if (key === undefined){ key = trimmed; origMap.set(node, key); }
    var entry = dict[key];
    if (!entry) return;
    var target = entry[lang()] || key;
    var lead = cur.match(/^\s*/)[0], tail = cur.match(/\s*$/)[0];
    var next = lead + target + tail;
    if (node.nodeValue !== next) node.nodeValue = next;
  }
  function walkTextNodes(root){
    var start = (root.nodeType === 9) ? root.body : root;
    if (!start) return;
    if (start.nodeType === 3){ translateTextNode(start); return; }
    if (start.nodeType !== 1) return;
    var tw = document.createTreeWalker(start, NodeFilter.SHOW_TEXT, null);
    var batch = [], n;
    while ((n = tw.nextNode())) batch.push(n);
    for (var i = 0; i < batch.length; i++) translateTextNode(batch[i]);
    // include the root itself if it is an element whose direct children include text
  }
  function translatePlaceholderEl(el){
    var dict = window.I18N_C; if (!dict) return;
    if (!el || el.nodeType !== 1 || !el.hasAttribute('placeholder')) return;
    if (el.hasAttribute('data-i18n-ph')) return; // handled by t()
    var key = origPh.get(el);
    if (key === undefined){ key = (el.getAttribute('placeholder') || '').trim(); origPh.set(el, key); }
    var entry = dict[key];
    if (entry) el.setAttribute('placeholder', entry[lang()] || key);
  }
  function translatePlaceholders(root){
    var scope = (root.nodeType === 9 || (root.nodeType === 1 && root.querySelectorAll)) ? root : document;
    // the root element itself may carry a placeholder (observer passes bare inputs)
    if (root.nodeType === 1) translatePlaceholderEl(root);
    var els;
    try { els = scope.querySelectorAll('[placeholder]'); } catch(e){ return; }
    for (var i = 0; i < els.length; i++) translatePlaceholderEl(els[i]);
  }
  window.i18nWalk = function(root){
    if (!window.I18N_C) return;
    root = root || document;
    walkTextNodes(root);
    translatePlaceholders(root);
  };
  var scheduled = false, pending = [];
  window.i18nObserve = function(){
    if (window.__i18nObs || !document.body) return;
    var obs = new MutationObserver(function(muts){
      for (var i = 0; i < muts.length; i++){
        var added = muts[i].addedNodes;
        for (var j = 0; j < added.length; j++){
          var an = added[j];
          if (an.nodeType === 1 || an.nodeType === 3) pending.push(an);
        }
      }
      if (!scheduled && pending.length){
        scheduled = true;
        // setTimeout (not requestAnimationFrame): rAF is paused in hidden/background
        // tabs, which would defer translation of freshly-rendered UI indefinitely.
        setTimeout(function(){
          scheduled = false;
          var roots = pending; pending = [];
          for (var k = 0; k < roots.length; k++){
            var r = roots[k];
            try {
              if (r.nodeType === 3) translateTextNode(r);
              else { walkTextNodes(r); translatePlaceholders(r); }
            } catch(e){}
          }
        }, 16);
      }
    });
    obs.observe(document.body, { childList: true, subtree: true });
    window.__i18nObs = obs;
  };
})();

